// MMI homepage v2 installer (self-styled, no Tailwind dependency).
// Run from your project root:  node install_homepage_v2.mjs
import fs from 'fs'
import path from 'path'
import os from 'os'
import { execSync } from 'child_process'

const FILES = {"FinalCTASection.tsx":"'use client'\n\nimport { ArrowRight } from 'lucide-react'\nimport { Reveal, type CtaProps } from './shared'\n\nexport default function FinalCTASection({ onAuth }: CtaProps) {\n  return (\n    <section className=\"mh-sec\">\n      <div className=\"mh-wrap\">\n        <Reveal>\n          <div className=\"mh-cta\">\n            <div className=\"mh-blob\" style={{ width: 300, height: 300, background: '#60A5FA', top: -100, left: -60 }} />\n            <div className=\"mh-blob\" style={{ width: 300, height: 300, background: '#C084FC', bottom: -120, right: -60, animationDelay: '-7s' }} />\n            <h2>Ready for your first peer interview?</h2>\n            <p>Sign in, pick your field, and find someone to practice with.</p>\n            <button className=\"mh-btn mh-btn-white\" onClick={onAuth}>Get started <ArrowRight size={18} aria-hidden=\"true\" /></button>\n          </div>\n        </Reveal>\n      </div>\n    </section>\n  )\n}\n","GuestHomepage.tsx":"'use client'\n\nimport './marketing.css'\nimport MarketingNav from './MarketingNav'\nimport HeroSection from './HeroSection'\nimport ProductLoopSection from './ProductLoopSection'\nimport TwoSidedValueSection from './TwoSidedValueSection'\nimport SkillValidationSection from './SkillValidationSection'\nimport PortfolioPreviewSection from './PortfolioPreviewSection'\nimport ResumeVsEvidenceSection from './ResumeVsEvidenceSection'\nimport VoiceInterviewSection from './VoiceInterviewSection'\nimport TalentPreviewSection from './TalentPreviewSection'\nimport SocialProofSection from './SocialProofSection'\nimport FinalCTASection from './FinalCTASection'\nimport MarketingFooter from './MarketingFooter'\nimport type { CtaProps } from './shared'\n\n// users, onlineCount and coffeesShared are accepted for compatibility with page.tsx\n// but intentionally unused: the homepage no longer shows unverified stats.\ntype Props = CtaProps & {\n  users?: unknown\n  onlineCount?: number\n  coffeesShared?: number\n}\n\nexport default function GuestHomepage({ onAuth }: Props) {\n  return (\n    <div className=\"mh\">\n      <MarketingNav onAuth={onAuth} />\n      <main>\n        <HeroSection onAuth={onAuth} />\n        <ProductLoopSection />\n        <VoiceInterviewSection />\n        <TwoSidedValueSection />\n        <SkillValidationSection />\n        <PortfolioPreviewSection />\n        <ResumeVsEvidenceSection />\n        <SocialProofSection />\n        <TalentPreviewSection />\n        <FinalCTASection onAuth={onAuth} />\n      </main>\n      <MarketingFooter />\n    </div>\n  )\n}\n","HeroSection.tsx":"'use client'\n\nimport { useEffect, useState } from 'react'\nimport { AnimatePresence, motion } from 'framer-motion'\nimport { ArrowRight, Briefcase, Check, Mic, ShieldCheck, Users, MessageSquare } from 'lucide-react'\nimport { Meter, PreviewBadge, Reveal, StatusBadge, Waveform, type CtaProps } from './shared'\n\nconst roles = ['Software and IT roles', 'Data and analytics roles', 'Banking and finance roles', 'Government roles', 'Consulting roles']\nconst ticks = [\n  { icon: Users, t: 'Same-field matching' },\n  { icon: Mic, t: 'Voice-only sessions' },\n  { icon: ShieldCheck, t: 'Anonymous profiles' },\n  { icon: MessageSquare, t: 'Text chat alongside' },\n  { icon: Briefcase, t: 'Government and private sector' },\n  { icon: Check, t: 'Both sides practice' },\n]\n\nexport default function HeroSection({ onAuth }: CtaProps) {\n  const [i, setI] = useState(0)\n  useEffect(() => {\n    const t = setInterval(() => setI((v) => (v + 1) % roles.length), 2600)\n    return () => clearInterval(t)\n  }, [])\n\n  return (\n    <section className=\"mh-hero\">\n      <div className=\"mh-blob\" style={{ width: 380, height: 380, background: '#93C5FD', top: -80, right: '8%' }} />\n      <div className=\"mh-blob\" style={{ width: 320, height: 320, background: '#C4B5FD', top: 160, left: '-4%', animationDelay: '-5s' }} />\n      <div className=\"mh-blob\" style={{ width: 260, height: 260, background: '#A5F3FC', bottom: 40, right: '30%', animationDelay: '-9s' }} />\n\n      <div className=\"mh-wrap mh-hero-grid\">\n        <Reveal>\n          <span className=\"mh-pill\"><span className=\"mh-dot\" /> Peer interviews with real people</span>\n          <h1 className=\"mh-h1\">\n            Don&apos;t Just List Your Skills. <span className=\"mh-grad\">Prove Them.</span>\n          </h1>\n          <p className=\"mh-sub\">\n            MatchMyInterview pairs you with a real peer from your field for voice mock interviews. Practice, get\n            feedback, and build toward a portfolio backed by peer evidence.\n          </p>\n          <div className=\"mh-rotator\" aria-live=\"polite\">\n            <span>Practice for</span>\n            <AnimatePresence mode=\"wait\">\n              <motion.span\n                key={roles[i]}\n                className=\"mh-rot-word\"\n                initial={{ y: 18, opacity: 0 }}\n                animate={{ y: 0, opacity: 1 }}\n                exit={{ y: -18, opacity: 0 }}\n                transition={{ duration: 0.3 }}\n              >\n                {roles[i]}\n              </motion.span>\n            </AnimatePresence>\n          </div>\n          <div className=\"mh-cta-row\">\n            <button className=\"mh-btn mh-btn-primary\" onClick={onAuth}>Start practicing <ArrowRight size={18} aria-hidden=\"true\" /></button>\n            <a className=\"mh-btn mh-btn-ghost\" href=\"#how-it-works\">See how it works</a>\n          </div>\n          <ul className=\"mh-points\">\n            <li><Users size={16} aria-hidden=\"true\" /> Same-field matching</li>\n            <li><Mic size={16} aria-hidden=\"true\" /> Voice-only sessions</li>\n            <li><ShieldCheck size={16} aria-hidden=\"true\" /> Anonymous profiles</li>\n          </ul>\n        </Reveal>\n\n        <Reveal delay={0.12}>\n          <div className=\"mh-stage\" aria-label=\"Illustration of a peer interview session\">\n            <div className=\"mh-fl mh-fl-1\">\n              <div className=\"mh-row\">\n                <div className=\"mh-row\" style={{ gap: 10 }}>\n                  <span className=\"mh-avatar mh-av-a\">A</span>\n                  <div><p className=\"mh-bold\" style={{ fontSize: 14 }}>Candidate A</p><p className=\"mh-small\">Data and Analytics</p></div>\n                </div>\n                <span className=\"mh-online\">Voice session</span>\n              </div>\n              <Waveform bars={32} />\n              <div className=\"mh-row\">\n                <p className=\"mh-small\">Peer is interviewing</p>\n                <span className=\"mh-avatar mh-av-b\" style={{ width: 30, height: 30, fontSize: 12 }}>B</span>\n              </div>\n            </div>\n            <div className=\"mh-fl mh-fl-2\">\n              <div className=\"mh-row\"><span className=\"mh-bold\" style={{ fontSize: 14 }}>Structured feedback</span><StatusBadge status=\"soon\" /></div>\n              <Meter label=\"Technical knowledge\" value={78} />\n              <Meter label=\"Communication\" value={64} />\n              <Meter label=\"Problem solving\" value={85} />\n            </div>\n            <div className=\"mh-fl mh-fl-3\"><Check size={16} color=\"#2563EB\" aria-hidden=\"true\" /> SQL, peer-validated</div>\n            <div className=\"mh-fl-tag\"><PreviewBadge label=\"Illustration\" /></div>\n          </div>\n        </Reveal>\n      </div>\n\n      <div className=\"mh-marquee\" aria-hidden=\"true\">\n        <div className=\"mh-track\">\n          {[...ticks, ...ticks].map((x, k) => (\n            <span className=\"mh-tick\" key={k}><x.icon size={16} /> {x.t}</span>\n          ))}\n        </div>\n      </div>\n    </section>\n  )\n}\n","MarketingFooter.tsx":"import Link from 'next/link'\n\nconst links = [\n  { href: '/about', label: 'About' },\n  { href: '/blog', label: 'Blog' },\n  { href: '/contact', label: 'Contact' },\n  { href: '/privacy', label: 'Privacy' },\n  { href: '/terms', label: 'Terms' },\n  { href: '/cookies', label: 'Cookies' },\n  { href: '/refund', label: 'Refunds' },\n]\n\nexport default function MarketingFooter() {\n  return (\n    <footer className=\"mh-footer\">\n      <div className=\"mh-wrap mh-foot-in\">\n        <p style={{ fontSize: 14 }}>&copy; MatchMyInterview. Built in India.</p>\n        <nav aria-label=\"Footer\" className=\"mh-foot-links\">\n          {links.map((l) => <Link key={l.href} href={l.href}>{l.label}</Link>)}\n        </nav>\n      </div>\n    </footer>\n  )\n}\n","MarketingNav.tsx":"'use client'\n\nimport { useEffect, useState } from 'react'\nimport Link from 'next/link'\nimport { Menu, X } from 'lucide-react'\nimport { motion, useScroll, useSpring } from 'framer-motion'\nimport type { CtaProps } from './shared'\n\nconst links = [\n  { href: '#how-it-works', label: 'How it works' },\n  { href: '#skills', label: 'Skill evidence' },\n  { href: '/blog', label: 'Blog' },\n]\n\nexport default function MarketingNav({ onAuth }: CtaProps) {\n  const [scrolled, setScrolled] = useState(false)\n  const [open, setOpen] = useState(false)\n  const { scrollYProgress } = useScroll()\n  const scaleX = useSpring(scrollYProgress, { stiffness: 120, damping: 28 })\n\n  useEffect(() => {\n    const f = () => setScrolled(window.scrollY > 12)\n    window.addEventListener('scroll', f, { passive: true })\n    return () => window.removeEventListener('scroll', f)\n  }, [])\n\n  return (\n    <>\n      <motion.div className=\"mh-progress\" style={{ scaleX }} aria-hidden=\"true\" />\n      <header className={`mh-nav${scrolled ? ' scrolled' : ''}`}>\n        <nav aria-label=\"Main\" className=\"mh-wrap mh-nav-in\">\n          <Link href=\"/\" className=\"mh-logo\">\n            <span className=\"mh-logo-mark\">M</span>\n            <span>MatchMyInterview</span>\n          </Link>\n          <div className=\"mh-links\">\n            {links.map((l) => (\n              <Link key={l.href} href={l.href}>{l.label}</Link>\n            ))}\n            <button className=\"mh-btn mh-btn-primary mh-btn-sm\" onClick={onAuth}>Get started</button>\n          </div>\n          <button\n            className=\"mh-burger\"\n            aria-label={open ? 'Close menu' : 'Open menu'}\n            aria-expanded={open}\n            aria-controls=\"mh-mobile\"\n            onClick={() => setOpen((v) => !v)}\n          >\n            {open ? <X size={22} /> : <Menu size={22} />}\n          </button>\n        </nav>\n        {open && (\n          <div id=\"mh-mobile\" className=\"mh-mobile\">\n            {links.map((l) => (\n              <Link key={l.href} href={l.href} onClick={() => setOpen(false)}>{l.label}</Link>\n            ))}\n            <button className=\"mh-btn mh-btn-primary\" style={{ width: '100%', marginTop: 8 }} onClick={() => { setOpen(false); onAuth() }}>\n              Get started\n            </button>\n          </div>\n        )}\n      </header>\n    </>\n  )\n}\n","PortfolioPreviewSection.tsx":"'use client'\n\nimport { motion } from 'framer-motion'\nimport { Check } from 'lucide-react'\nimport { PreviewBadge, Reveal, SectionHeader } from './shared'\n\nconst bars = [['SQL', 82], ['Communication', 70], ['Problem solving', 76]] as const\n\nexport default function PortfolioPreviewSection() {\n  return (\n    <section className=\"mh-sec\" style={{ background: 'var(--soft)' }}>\n      <div className=\"mh-wrap\">\n        <SectionHeader eyebrow=\"Coming soon\" title=\"A portfolio built from real sessions\" description=\"Your profile will bring together your background, your skills, and the feedback you have earned.\" />\n        <div className=\"mh-pf\">\n          <Reveal>\n            <div className=\"mh-pf-card\" style={{ textAlign: 'center', height: '100%' }}>\n              <PreviewBadge label=\"Example preview\" />\n              <div className=\"mh-ring\">\n                <svg viewBox=\"0 0 120 120\" aria-hidden=\"true\">\n                  <circle cx=\"60\" cy=\"60\" r=\"50\" fill=\"none\" stroke=\"#E5EAF2\" strokeWidth=\"10\" />\n                  <motion.circle cx=\"60\" cy=\"60\" r=\"50\" fill=\"none\" stroke=\"url(#mhg)\" strokeWidth=\"10\" strokeLinecap=\"round\" initial={{ pathLength: 0 }} whileInView={{ pathLength: 0.72 }} viewport={{ once: true }} transition={{ duration: 1.4, ease: 'easeOut' }} />\n                  <defs><linearGradient id=\"mhg\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stopColor=\"#2563EB\" /><stop offset=\"1\" stopColor=\"#7C3AED\" /></linearGradient></defs>\n                </svg>\n                <div className=\"mh-ring-mid\">Profile<br />strength</div>\n              </div>\n              <p className=\"mh-bold\">Sample Candidate</p>\n              <p className=\"mh-small\">Data and Analytics</p>\n            </div>\n          </Reveal>\n          <Reveal delay={0.08}>\n            <div className=\"mh-pf-card\">\n              <p className=\"mh-bold\" style={{ marginBottom: 6 }}>Skills backed by evidence</p>\n              {bars.map(([l, v], k) => (\n                <div className=\"mh-meter\" key={l}>\n                  <div className=\"mh-meter-top\"><span>{l}</span></div>\n                  <div className=\"mh-meter-bar\">\n                    <motion.i initial={{ width: 0 }} whileInView={{ width: `${v}%` }} viewport={{ once: true }} transition={{ duration: 1, delay: 0.15 * k }} style={{ display: 'block', height: '100%', borderRadius: 99, background: 'linear-gradient(90deg,#2563EB,#7C3AED)' }} />\n                  </div>\n                </div>\n              ))}\n              <div style={{ marginTop: 18 }}>\n                {['Linked to specific peer sessions', 'You choose what is visible', 'Evidence, not certification'].map((t) => (\n                  <div className=\"mh-ev\" key={t}><span className=\"mh-tick-ico\"><Check size={14} aria-hidden=\"true\" /></span>{t}</div>\n                ))}\n              </div>\n            </div>\n          </Reveal>\n        </div>\n      </div>\n    </section>\n  )\n}\n","ProductLoopSection.tsx":"'use client'\n\nimport { useEffect, useState } from 'react'\nimport { AnimatePresence, motion } from 'framer-motion'\nimport { Award, FileText, Mic, Search, UserPlus } from 'lucide-react'\nimport { Meter, PreviewBadge, SectionHeader, StatusBadge, Waveform } from './shared'\n\nconst steps = [\n  { icon: UserPlus, title: 'Create your profile', body: 'Pick your domain, experience level and target role.', status: 'live' },\n  { icon: Search, title: 'Find a peer in your field', body: 'See who is active and send an invite.', status: 'live' },\n  { icon: Mic, title: 'Interview each other', body: 'Run a voice session, with text chat alongside.', status: 'live' },\n  { icon: FileText, title: 'Give structured feedback', body: 'Rate each other against a clear rubric.', status: 'soon' },\n  { icon: Award, title: 'Build skill evidence', body: 'Turn feedback into a portfolio you can share.', status: 'soon' },\n] as const\n\nfunction Panel({ i }: { i: number }) {\n  if (i === 0)\n    return (\n      <div className=\"mh-mock\">\n        <p className=\"mh-bold\">Your profile</p>\n        <div className=\"mh-field\"><span>Domain</span><span>Data and Analytics</span></div>\n        <div className=\"mh-field\"><span>Experience</span><span>0-2 yrs</span></div>\n        <div className=\"mh-field\"><span>Target role</span><span>Business Analyst</span></div>\n      </div>\n    )\n  if (i === 1)\n    return (\n      <div className=\"mh-mock\">\n        <p className=\"mh-bold\">Peers in your field</p>\n        {['A', 'B', 'C'].map((l, k) => (\n          <div className=\"mh-peer\" key={l}>\n            <span className={`mh-avatar ${k % 2 ? 'mh-av-b' : 'mh-av-a'}`}>{l}</span>\n            <div className=\"grow\"><p className=\"mh-bold\" style={{ fontSize: 14 }}>Anonymous peer</p><span className=\"mh-online\">Active now</span></div>\n            <span className=\"mh-btn mh-btn-primary mh-btn-sm\" aria-hidden=\"true\">Invite</span>\n          </div>\n        ))}\n      </div>\n    )\n  if (i === 2)\n    return (\n      <div className=\"mh-mock\">\n        <div className=\"mh-row\"><p className=\"mh-bold\">Voice session</p><span className=\"mh-online\">Connected</span></div>\n        <Waveform bars={36} />\n        <div className=\"mh-bubble l\">Walk me through a project where you used SQL.</div>\n        <div className=\"mh-bubble r\">Sure. I built a report that joined three tables to track monthly trends.</div>\n      </div>\n    )\n  if (i === 3)\n    return (\n      <div className=\"mh-mock\">\n        <p className=\"mh-bold\">Example rubric</p>\n        <Meter label=\"Technical knowledge\" value={78} />\n        <Meter label=\"Communication\" value={64} />\n        <Meter label=\"Problem solving\" value={85} />\n        <p className=\"mh-small\" style={{ marginTop: 14 }}>A written justification accompanies every rating.</p>\n      </div>\n    )\n  return (\n    <div className=\"mh-mock\">\n      <div className=\"mh-row\"><p className=\"mh-bold\">Your portfolio</p><span className=\"mh-badge mh-b-soon\">Shareable</span></div>\n      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 14 }}>\n        {['SQL', 'Communication', 'Excel'].map((s) => <span className=\"mh-chip valid\" key={s}>{s}</span>)}\n      </div>\n      <p className=\"mh-small\" style={{ marginTop: 14 }}>Each validated skill links back to the sessions that earned it.</p>\n    </div>\n  )\n}\n\nexport default function ProductLoopSection() {\n  const [active, setActive] = useState(0)\n  const [auto, setAuto] = useState(true)\n\n  useEffect(() => {\n    if (!auto) return\n    const t = setTimeout(() => setActive((v) => (v + 1) % steps.length), 5000)\n    return () => clearTimeout(t)\n  }, [active, auto])\n\n  return (\n    <section id=\"how-it-works\" className=\"mh-sec\" style={{ scrollMarginTop: 70 }}>\n      <div className=\"mh-wrap\">\n        <SectionHeader eyebrow=\"How it works\" title=\"Practice with a peer. Leave with evidence.\" description=\"Everyone plays both roles, so you learn from being interviewed and from interviewing.\" />\n        <div className=\"mh-loop\">\n          <div className=\"mh-steps\" role=\"tablist\" aria-label=\"How MatchMyInterview works\">\n            {steps.map((s, k) => (\n              <button\n                key={s.title}\n                role=\"tab\"\n                aria-selected={active === k}\n                className={`mh-step${active === k ? ' on' : ''}${auto ? ' auto' : ''}`}\n                onClick={() => { setAuto(false); setActive(k) }}\n              >\n                <span className=\"mh-step-num\">{k + 1}</span>\n                <span>\n                  <span className=\"mh-step-title\">{s.title} <StatusBadge status={s.status} /></span>\n                  <span className=\"mh-step-body\" style={{ display: 'block' }}>{s.body}</span>\n                </span>\n                <span className=\"mh-step-bar\"><i key={`${active}-${auto}`} /></span>\n              </button>\n            ))}\n          </div>\n          <div className=\"mh-panel\" role=\"tabpanel\">\n            <div className=\"mh-panel-top\">\n              <span className=\"mh-bold\">Step {active + 1}: {steps[active].title}</span>\n              <PreviewBadge label=\"Illustration\" />\n            </div>\n            <AnimatePresence mode=\"wait\">\n              <motion.div key={active} initial={{ opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={{ duration: 0.28 }}>\n                <Panel i={active} />\n              </motion.div>\n            </AnimatePresence>\n          </div>\n        </div>\n      </div>\n    </section>\n  )\n}\n","ResumeVsEvidenceSection.tsx":"'use client'\n\nimport { Check } from 'lucide-react'\nimport { Reveal, SectionHeader } from './shared'\n\nexport default function ResumeVsEvidenceSection() {\n  return (\n    <section className=\"mh-sec\">\n      <div className=\"mh-wrap\">\n        <SectionHeader title={<>A resume makes claims.<br /><span className=\"mh-grad\">Evidence shows how you perform.</span></>} />\n        <div className=\"mh-cmp\">\n          <Reveal>\n            <div className=\"mh-cmp-a\" style={{ height: '100%' }}>\n              <p className=\"mh-bold\" style={{ color: '#64748B', marginBottom: 8 }}>A resume says</p>\n              {['Strong communication skills', 'Proficient in SQL', 'Good problem solver'].map((c) => (\n                <div className=\"mh-claim\" key={c}><span>&ldquo;{c}&rdquo;</span><span>?</span></div>\n              ))}\n            </div>\n          </Reveal>\n          <Reveal delay={0.1}>\n            <div className=\"mh-cmp-b\" style={{ height: '100%' }}>\n              <div>\n                <p className=\"mh-bold\" style={{ color: '#2563EB', marginBottom: 8 }}>MMI evidence will show <span className=\"mh-badge mh-b-soon\">Coming soon</span></p>\n                <ul className=\"mh-list\">\n                  {['Feedback from peers who interviewed you', 'Skills linked to specific sessions', 'Progress across multiple interviews'].map((c) => (\n                    <li key={c}><span className=\"mh-tick-ico\"><Check size={15} aria-hidden=\"true\" /></span>{c}</li>\n                  ))}\n                </ul>\n              </div>\n            </div>\n          </Reveal>\n        </div>\n      </div>\n    </section>\n  )\n}\n","SkillValidationSection.tsx":"'use client'\n\nimport { useEffect, useRef, useState } from 'react'\nimport { AnimatePresence, motion } from 'framer-motion'\nimport { Check, Play, RotateCcw } from 'lucide-react'\nimport { Meter, PreviewBadge, SectionHeader, Waveform } from './shared'\n\ntype Phase = 'idle' | 'running' | 'done'\nconst skills = ['SQL', 'Communication', 'Python', 'Power BI', 'Statistics']\nconst evidenced = ['SQL', 'Communication']\n\nexport default function SkillValidationSection() {\n  const [phase, setPhase] = useState<Phase>('idle')\n  const timer = useRef<ReturnType<typeof setTimeout> | null>(null)\n  useEffect(() => () => { if (timer.current) clearTimeout(timer.current) }, [])\n\n  const run = () => {\n    setPhase('running')\n    timer.current = setTimeout(() => setPhase('done'), 2200)\n  }\n  const reset = () => {\n    if (timer.current) clearTimeout(timer.current)\n    setPhase('idle')\n  }\n  const validated = (s: string) => phase === 'done' && evidenced.includes(s)\n\n  return (\n    <section id=\"skills\" className=\"mh-sec mh-dark\" style={{ scrollMarginTop: 70 }}>\n      <div className=\"mh-wrap\">\n        <SectionHeader\n          eyebrow=\"Skill evidence\"\n          title=\"Claimed skills and proven skills look different\"\n          description=\"You can list any skill you like. Only feedback from real peer interviews can validate it, and you can never edit a validation yourself.\"\n        />\n        <div className=\"mh-demo\">\n          <div className=\"mh-demo-top\">\n            <span style={{ fontWeight: 700 }}>Interactive demo: sample profile</span>\n            <PreviewBadge label=\"Simulated, not real data\" />\n          </div>\n\n          <p className=\"mh-lbl\">Skills</p>\n          <div className=\"mh-chips\">\n            {skills.map((s) => (\n              <motion.span key={s} layout className={`mh-chip ${validated(s) ? 'valid' : 'self'}`}>\n                {validated(s) ? <Check size={14} aria-hidden=\"true\" /> : null}\n                {s}\n                <span style={{ fontSize: 11, opacity: 0.8, fontWeight: 500 }}>{validated(s) ? 'peer-validated' : 'self-declared'}</span>\n              </motion.span>\n            ))}\n          </div>\n\n          <AnimatePresence mode=\"wait\">\n            {phase === 'running' && (\n              <motion.div key=\"run\" className=\"mh-sim\" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }}>\n                <p style={{ fontWeight: 600 }}>A peer is interviewing you on SQL and communication...</p>\n                <Waveform bars={44} />\n              </motion.div>\n            )}\n            {phase === 'done' && (\n              <motion.div key=\"done\" className=\"mh-sim\" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }}>\n                <p style={{ fontWeight: 600 }}>Peer feedback received</p>\n                <Meter label=\"SQL\" value={82} />\n                <Meter label=\"Communication\" value={70} />\n                <p className=\"mh-demo-note\" style={{ marginTop: 14 }}>Python, Power BI and Statistics stay self-declared because no peer has evaluated them.</p>\n              </motion.div>\n            )}\n          </AnimatePresence>\n\n          <div style={{ display: 'flex', gap: 10, marginTop: 24, flexWrap: 'wrap' }}>\n            {phase === 'idle' && <button className=\"mh-btn mh-btn-light mh-btn-sm\" onClick={run}><Play size={16} aria-hidden=\"true\" /> Simulate a peer interview</button>}\n            {phase !== 'idle' && <button className=\"mh-btn mh-btn-glass mh-btn-sm\" onClick={reset}><RotateCcw size={16} aria-hidden=\"true\" /> Reset demo</button>}\n          </div>\n          <p className=\"mh-demo-note\">\n            In the real product, only a peer&apos;s feedback can change a skill&apos;s status. Validation is evidence of practice performance, not a formal certification. This feature is coming soon.\n          </p>\n        </div>\n      </div>\n    </section>\n  )\n}\n","SocialProofSection.tsx":"'use client'\n\nimport { Check, Clock } from 'lucide-react'\nimport { Reveal, SectionHeader } from './shared'\n\nconst live = ['Peer matching by domain and role', 'Voice sessions with text chat', 'Invites and session flow', 'Blog with interview guides']\nconst next = ['Skills on your profile', 'Structured peer feedback', 'Peer-validated skill evidence', 'Shareable portfolio']\n\nexport default function SocialProofSection() {\n  return (\n    <section className=\"mh-sec\" style={{ background: 'var(--soft)' }}>\n      <div className=\"mh-wrap\">\n        <SectionHeader eyebrow=\"Built in public\" title=\"What works today, and what is next\" description=\"We would rather show you our progress than invent numbers.\" />\n        <div className=\"mh-road\">\n          <Reveal>\n            <div className=\"mh-road-card\" style={{ height: '100%' }}>\n              <h3 className=\"mh-h3\">Live now</h3>\n              <ul style={{ marginTop: 10 }}>\n                {live.map((x) => <li key={x}><span className=\"mh-tick-ico\" style={{ background: '#D1FAE5', color: '#047857' }}><Check size={15} aria-hidden=\"true\" /></span>{x}</li>)}\n              </ul>\n            </div>\n          </Reveal>\n          <Reveal delay={0.1}>\n            <div className=\"mh-road-card\" style={{ height: '100%' }}>\n              <h3 className=\"mh-h3\">Coming next</h3>\n              <ul style={{ marginTop: 10 }}>\n                {next.map((x) => <li key={x} style={{ color: '#475569' }}><span className=\"mh-tick-ico\"><Clock size={14} aria-hidden=\"true\" /></span>{x}</li>)}\n              </ul>\n            </div>\n          </Reveal>\n        </div>\n      </div>\n    </section>\n  )\n}\n","TalentPreviewSection.tsx":"'use client'\n\nimport { Lock } from 'lucide-react'\nimport { Reveal, StatusBadge } from './shared'\n\nexport default function TalentPreviewSection() {\n  return (\n    <section className=\"mh-sec\" style={{ paddingTop: 0 }}>\n      <div className=\"mh-wrap\">\n        <Reveal>\n          <div className=\"mh-talent\">\n            <StatusBadge status=\"planned\" />\n            <h2 className=\"mh-h2\" style={{ marginTop: 16, fontSize: 'clamp(1.6rem,3vw,2.3rem)' }}>Where this is heading</h2>\n            <p className=\"mh-lead\" style={{ maxWidth: 560, margin: '14px auto 0' }}>\n              Longer term, we want strong, evidence-backed profiles to be discoverable by companies, with you in control of what is shared. This is a direction, not something you can use today.\n            </p>\n            <div aria-hidden=\"true\" style={{ marginTop: 26 }}>\n              {[70, 55, 62].map((w, k) => (\n                <div className=\"mh-skel\" key={k}><i style={{ width: 36, height: 36, borderRadius: '50%' }} /><i style={{ width: `${w}%` }} /></div>\n              ))}\n            </div>\n            <p className=\"mh-small\" style={{ marginTop: 18, display: 'inline-flex', alignItems: 'center', gap: 6 }}><Lock size={14} aria-hidden=\"true\" /> Opt-in only</p>\n          </div>\n        </Reveal>\n      </div>\n    </section>\n  )\n}\n","TwoSidedValueSection.tsx":"'use client'\n\nimport { useState } from 'react'\nimport { AnimatePresence, motion } from 'framer-motion'\nimport { Check } from 'lucide-react'\nimport { SectionHeader, Reveal } from './shared'\n\nconst roles = {\n  candidate: {\n    label: 'Candidate',\n    points: ['Practice answers out loud, not just in your head', 'Get feedback from someone in your own field', 'Build evidence of what you can do'],\n  },\n  interviewer: {\n    label: 'Interviewer',\n    points: ['Learn what good answers look like', 'Practice giving clear, useful feedback', 'Build a record of your contribution, kept separate from your candidate record'],\n  },\n} as const\n\nexport default function TwoSidedValueSection() {\n  const [role, setRole] = useState<keyof typeof roles>('candidate')\n  return (\n    <section className=\"mh-sec\">\n      <div className=\"mh-wrap\" style={{ textAlign: 'center' }}>\n        <SectionHeader eyebrow=\"Both sides\" title=\"Two roles. One person.\" description=\"You switch between candidate and interviewer, so every session helps you twice.\" />\n        <Reveal>\n          <div className=\"mh-seg\" role=\"tablist\" aria-label=\"Choose a role\">\n            {(Object.keys(roles) as (keyof typeof roles)[]).map((k) => (\n              <button key={k} role=\"tab\" aria-selected={role === k} className={role === k ? 'on' : ''} onClick={() => setRole(k)}>\n                {role === k && <motion.span layoutId=\"mh-seg-pill\" className=\"mh-seg-pill\" transition={{ type: 'spring', stiffness: 400, damping: 32 }} />}\n                <span style={{ position: 'relative' }}>{roles[k].label}</span>\n              </button>\n            ))}\n          </div>\n        </Reveal>\n        <div style={{ maxWidth: 640, margin: '36px auto 0', textAlign: 'left', minHeight: 240 }}>\n          <AnimatePresence mode=\"wait\">\n            <motion.ul key={role} className=\"mh-list\" initial={{ opacity: 0, x: 24 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -24 }} transition={{ duration: 0.28 }}>\n              {roles[role].points.map((p) => (\n                <li key={p}><span className=\"mh-tick-ico\"><Check size={15} aria-hidden=\"true\" /></span>{p}</li>\n              ))}\n            </motion.ul>\n          </AnimatePresence>\n        </div>\n      </div>\n    </section>\n  )\n}\n","VoiceInterviewSection.tsx":"'use client'\n\nimport { Briefcase, Mic, ShieldCheck, Users } from 'lucide-react'\nimport { GlowCard, Reveal, SectionHeader, StatusBadge, Waveform } from './shared'\n\nconst features = [\n  { icon: Users, c: 'mh-i1', title: 'Same-field matching', body: 'Find peers by domain and target role, and see who is active right now.' },\n  { icon: Mic, c: 'mh-i2', title: 'Voice-only sessions', body: 'Talk through answers like a real interview, with text chat alongside.', wave: true },\n  { icon: ShieldCheck, c: 'mh-i3', title: 'Anonymous profiles', body: 'Practice without putting your identity on display.' },\n  { icon: Briefcase, c: 'mh-i4', title: 'Government and private sector', body: 'Prepare for either path with peers who understand it.' },\n]\n\nexport default function VoiceInterviewSection() {\n  return (\n    <section className=\"mh-sec\" style={{ background: 'var(--soft)' }}>\n      <div className=\"mh-wrap\">\n        <SectionHeader eyebrow=\"Available today\" title=\"Voice practice that feels like the real thing\" description=\"Everything below works today.\" />\n        <div className=\"mh-bento\">\n          {features.map((f, k) => (\n            <Reveal key={f.title} delay={k * 0.06}>\n              <GlowCard>\n                <span className={`mh-ico ${f.c}`}><f.icon size={24} aria-hidden=\"true\" /></span>\n                <h3 className=\"mh-h3\">{f.title} <StatusBadge status=\"live\" /></h3>\n                <p className=\"mh-card-p\">{f.body}</p>\n                {f.wave && <Waveform bars={40} />}\n              </GlowCard>\n            </Reveal>\n          ))}\n        </div>\n      </div>\n    </section>\n  )\n}\n","marketing.css":"/* MMI homepage styles. Self-contained: does not rely on Tailwind. All classes are prefixed mh- and scoped under .mh */\n.mh{--ink:#0B1220;--muted:#5B6B82;--line:#E5EAF2;--primary:#2563EB;--violet:#7C3AED;--cyan:#06B6D4;--navy:#0B1929;--soft:#F5F8FF;\n  font-family:var(--font-inter),system-ui,-apple-system,\"Segoe UI\",sans-serif;color:var(--ink);background:#fff;line-height:1.6;overflow-x:clip;-webkit-font-smoothing:antialiased}\n:where(.mh) *,:where(.mh) *::before,:where(.mh) *::after{box-sizing:border-box}\n:where(.mh) h1,:where(.mh) h2,:where(.mh) h3,:where(.mh) p,:where(.mh) ul,:where(.mh) ol{margin:0;padding:0}\n:where(.mh) ul,:where(.mh) ol{list-style:none}\n:where(.mh) a{color:inherit;text-decoration:none}\n:where(.mh) button{font:inherit;cursor:pointer;border:0;background:none;color:inherit;padding:0}\n\n.mh-wrap{max-width:1160px;margin:0 auto;padding:0 20px}\n.mh-sec{padding:100px 0;position:relative}\n@media(max-width:700px){.mh-sec{padding:64px 0}}\n\n/* progress + nav */\n.mh-progress{position:fixed;top:0;left:0;right:0;height:3px;background:linear-gradient(90deg,#2563EB,#7C3AED,#06B6D4);transform-origin:0 50%;z-index:70}\n.mh-nav{position:sticky;top:0;z-index:60;transition:background .3s,border-color .3s,box-shadow .3s;border-bottom:1px solid transparent}\n.mh-nav.scrolled{background:rgba(255,255,255,.82);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border-color:var(--line);box-shadow:0 6px 24px -18px rgba(15,23,42,.4)}\n.mh-nav-in{display:flex;align-items:center;justify-content:space-between;height:68px}\n.mh-logo{display:flex;align-items:center;gap:10px;font-weight:800;font-size:18px;letter-spacing:-.02em}\n.mh-logo-mark{width:32px;height:32px;border-radius:10px;background:linear-gradient(135deg,#2563EB,#7C3AED);display:grid;place-items:center;color:#fff;font-size:14px;font-weight:800}\n.mh-links{display:flex;align-items:center;gap:28px}\n.mh-links a{font-size:14px;font-weight:500;color:var(--muted);transition:color .2s}\n.mh-links a:hover{color:var(--ink)}\n.mh-burger{display:none;width:44px;height:44px;border-radius:12px;align-items:center;justify-content:center}\n.mh-mobile{border-top:1px solid var(--line);background:#fff;padding:8px 20px 20px}\n.mh-mobile a{display:flex;align-items:center;min-height:48px;font-weight:600}\n@media(max-width:820px){.mh-links{display:none}.mh-burger{display:flex}}\n\n/* buttons */\n.mh-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:48px;padding:0 26px;border-radius:14px;font-weight:600;font-size:16px;transition:transform .25s,box-shadow .25s,background .25s;position:relative;overflow:hidden}\n.mh-btn:focus-visible{outline:3px solid #93C5FD;outline-offset:3px}\n.mh-btn-primary{background:linear-gradient(135deg,#2563EB,#4F46E5);color:#fff;box-shadow:0 12px 30px -12px rgba(37,99,235,.8)}\n.mh-btn-primary:hover{transform:translateY(-2px);box-shadow:0 18px 36px -12px rgba(37,99,235,.9)}\n.mh-btn-primary::after{content:\"\";position:absolute;top:0;left:-120%;width:60%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.35),transparent);transform:skewX(-20deg);animation:mh-sheen 4s ease-in-out infinite}\n.mh-btn-ghost{background:#fff;border:1px solid var(--line);color:var(--ink)}\n.mh-btn-ghost:hover{border-color:#BFD0F5;transform:translateY(-2px);box-shadow:0 10px 24px -16px rgba(37,99,235,.5)}\n.mh-btn-white{background:#fff;color:#1E3A8A}\n.mh-btn-white:hover{transform:translateY(-2px);box-shadow:0 18px 40px -14px rgba(0,0,0,.5)}\n.mh-btn-sm{min-height:40px;padding:0 18px;font-size:14px;border-radius:12px}\n\n/* badges */\n.mh-badge{display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:2px 10px;font-size:12px;font-weight:700;border:1px solid transparent;white-space:nowrap}\n.mh-b-live{background:#ECFDF5;color:#047857;border-color:#A7F3D0}\n.mh-b-soon{background:#EFF6FF;color:#1D4ED8;border-color:#BFDBFE}\n.mh-b-planned{background:#F1F5F9;color:#475569;border-color:#E2E8F0}\n.mh-b-preview{background:#FFFBEB;color:#92400E;border-color:#FDE68A}\n\n/* hero */\n.mh-hero{position:relative;overflow:hidden;padding:56px 0 0;background:radial-gradient(1100px 520px at 85% -10%,#DCE8FF 0,transparent 60%),radial-gradient(800px 480px at -10% 15%,#EFE6FF 0,transparent 58%),#fff}\n.mh-blob{position:absolute;border-radius:50%;filter:blur(80px);opacity:.45;pointer-events:none;animation:mh-drift 16s ease-in-out infinite}\n.mh-hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:48px;align-items:center;position:relative;z-index:1;padding-bottom:64px}\n@media(max-width:960px){.mh-hero-grid{grid-template-columns:1fr;gap:40px}}\n.mh-pill{display:inline-flex;align-items:center;gap:10px;background:#fff;border:1px solid var(--line);border-radius:999px;padding:6px 14px 6px 10px;font-size:13px;font-weight:600;color:#1D4ED8;box-shadow:0 8px 24px -16px rgba(37,99,235,.6)}\n.mh-dot{width:8px;height:8px;border-radius:50%;background:#10B981;box-shadow:0 0 0 0 rgba(16,185,129,.6);animation:mh-pulse 2s infinite}\n.mh-h1{font-size:clamp(2.5rem,5.6vw,4.4rem);line-height:1.04;letter-spacing:-.04em;font-weight:800;margin-top:22px}\n.mh-grad{background:linear-gradient(90deg,#2563EB,#7C3AED,#06B6D4,#2563EB);background-size:220% auto;-webkit-background-clip:text;background-clip:text;color:transparent;animation:mh-shine 7s linear infinite}\n.mh-sub{font-size:clamp(1rem,1.6vw,1.2rem);color:var(--muted);max-width:560px;margin-top:22px}\n.mh-rotator{display:flex;align-items:center;gap:8px;height:34px;margin-top:20px;font-weight:600;font-size:16px;color:var(--ink);overflow:hidden}\n.mh-rotator span.mh-rot-word{display:inline-block;color:#2563EB}\n.mh-cta-row{display:flex;gap:12px;flex-wrap:wrap;margin-top:30px}\n.mh-points{display:flex;flex-wrap:wrap;gap:10px 24px;margin-top:30px;font-size:14px;color:var(--muted)}\n.mh-points li{display:flex;align-items:center;gap:8px}\n.mh-points svg{color:#2563EB}\n\n.mh-stage{position:relative;height:470px}\n@media(max-width:560px){.mh-stage{height:430px}}\n.mh-fl{position:absolute;background:#fff;border:1px solid var(--line);border-radius:20px;padding:16px;box-shadow:0 30px 60px -30px rgba(30,58,138,.45)}\n.mh-fl-1{left:0;top:34px;width:80%;animation:mh-bob 7s ease-in-out infinite}\n.mh-fl-2{right:0;bottom:6px;width:68%;animation:mh-bob 8s ease-in-out -2s infinite}\n.mh-fl-3{right:4%;top:0;padding:10px 14px;border-radius:999px;display:flex;align-items:center;gap:8px;font-weight:700;font-size:13px;animation:mh-bob 6s ease-in-out -1s infinite}\n.mh-fl-tag{position:absolute;left:0;bottom:-6px}\n.mh-row{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.mh-avatar{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;color:#fff;font-weight:700;font-size:14px}\n.mh-av-a{background:linear-gradient(135deg,#2563EB,#06B6D4)}\n.mh-av-b{background:linear-gradient(135deg,#7C3AED,#EC4899)}\n.mh-wave{display:flex;align-items:center;gap:3px;height:40px;margin:14px 0 8px}\n.mh-wave i{display:block;flex:1;max-width:5px;height:100%;border-radius:3px;background:linear-gradient(#2563EB,#7C3AED);transform-origin:center;animation:mh-bar 1.2s ease-in-out infinite}\n.mh-meter{margin-top:10px}\n.mh-meter-top{display:flex;justify-content:space-between;font-size:12px;font-weight:600;color:var(--muted);margin-bottom:5px}\n.mh-meter-bar{height:8px;border-radius:99px;background:#EEF2F9;overflow:hidden}\n.mh-meter-bar i{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,#2563EB,#7C3AED)}\n.mh-small{font-size:12px;color:var(--muted)}\n.mh-bold{font-weight:700}\n\n.mh-marquee{position:relative;z-index:1;overflow:hidden;border-top:1px solid var(--line);background:rgba(255,255,255,.7);padding:18px 0;-webkit-mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent);mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent)}\n.mh-track{display:flex;gap:14px;width:max-content;animation:mh-scroll 34s linear infinite}\n.mh-marquee:hover .mh-track{animation-play-state:paused}\n.mh-tick{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--line);background:#fff;border-radius:999px;padding:8px 16px;font-size:14px;font-weight:600;color:#334155;white-space:nowrap}\n.mh-tick svg{color:#2563EB}\n\n/* headings */\n.mh-head{max-width:680px;margin:0 auto;text-align:center}\n.mh-eyebrow{display:inline-block;font-size:13px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#2563EB;background:#EFF6FF;border-radius:999px;padding:5px 14px;margin-bottom:16px}\n.mh-h2{font-size:clamp(1.9rem,3.8vw,3rem);line-height:1.1;letter-spacing:-.03em;font-weight:800}\n.mh-lead{margin-top:16px;color:var(--muted);font-size:clamp(1rem,1.5vw,1.15rem)}\n.mh-dark .mh-lead{color:#A9B8D0}\n.mh-dark .mh-eyebrow{background:rgba(96,165,250,.15);color:#93C5FD}\n\n/* loop */\n.mh-loop{display:grid;grid-template-columns:.85fr 1.15fr;gap:32px;margin-top:56px;align-items:stretch}\n@media(max-width:900px){.mh-loop{grid-template-columns:1fr}}\n.mh-steps{display:flex;flex-direction:column;gap:10px}\n.mh-step{position:relative;text-align:left;display:flex;gap:14px;padding:16px 18px;border-radius:18px;border:1px solid var(--line);background:#fff;transition:all .3s;overflow:hidden;width:100%}\n.mh-step:hover{border-color:#BFD0F5;transform:translateX(3px)}\n.mh-step:focus-visible{outline:3px solid #93C5FD;outline-offset:2px}\n.mh-step.on{border-color:#93B4F8;background:linear-gradient(180deg,#F7FAFF,#EEF4FF);box-shadow:0 18px 40px -26px rgba(37,99,235,.7)}\n.mh-step-num{flex:none;width:36px;height:36px;border-radius:11px;display:grid;place-items:center;background:#F1F5F9;color:#64748B;font-weight:800;font-size:14px;transition:.3s}\n.mh-step.on .mh-step-num{background:linear-gradient(135deg,#2563EB,#7C3AED);color:#fff}\n.mh-step-title{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-weight:700}\n.mh-step-body{font-size:14px;color:var(--muted);margin-top:2px}\n.mh-step-bar{position:absolute;left:0;bottom:0;height:3px;width:100%;background:transparent}\n.mh-step-bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#2563EB,#7C3AED)}\n.mh-step.on.auto .mh-step-bar i{animation:mh-fill 5s linear forwards}\n.mh-step.on:not(.auto) .mh-step-bar i{width:100%}\n.mh-panel{border:1px solid var(--line);border-radius:26px;padding:22px;min-height:420px;background:radial-gradient(500px 280px at 90% 0,#E6EEFF,transparent 70%),linear-gradient(180deg,#FAFCFF,#F2F6FF);position:relative;overflow:hidden}\n.mh-panel-top{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:18px;flex-wrap:wrap}\n.mh-mock{background:#fff;border:1px solid var(--line);border-radius:18px;padding:18px;box-shadow:0 20px 40px -28px rgba(30,58,138,.4)}\n.mh-field{display:flex;justify-content:space-between;align-items:center;padding:12px 14px;border:1px solid var(--line);border-radius:12px;margin-top:10px;font-size:14px}\n.mh-field span:first-child{color:var(--muted);font-weight:600}\n.mh-peer{display:flex;align-items:center;gap:12px;padding:12px;border:1px solid var(--line);border-radius:14px;margin-top:10px;background:#fff}\n.mh-peer .grow{flex:1;min-width:0}\n.mh-online{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:#047857;font-weight:600}\n.mh-online::before{content:\"\";width:7px;height:7px;border-radius:50%;background:#10B981}\n.mh-bubble{max-width:82%;padding:10px 14px;border-radius:16px;font-size:14px;margin-top:10px}\n.mh-bubble.l{background:#F1F5F9;border-bottom-left-radius:4px}\n.mh-bubble.r{background:linear-gradient(135deg,#2563EB,#4F46E5);color:#fff;margin-left:auto;border-bottom-right-radius:4px}\n\n/* bento */\n.mh-bento{display:grid;grid-template-columns:repeat(6,1fr);gap:16px;margin-top:56px}\n.mh-bento>*:nth-child(1){grid-column:span 4}.mh-bento>*:nth-child(2){grid-column:span 2}\n.mh-bento>*:nth-child(3){grid-column:span 2}.mh-bento>*:nth-child(4){grid-column:span 4}\n@media(max-width:820px){.mh-bento>*{grid-column:span 6!important}}\n.mh-glow{position:relative;border:1px solid var(--line);border-radius:24px;background:#fff;padding:26px;overflow:hidden;transition:transform .3s,box-shadow .3s,border-color .3s}\n.mh-glow::before{content:\"\";position:absolute;inset:0;pointer-events:none;background:radial-gradient(420px circle at var(--mx,50%) var(--my,50%),rgba(37,99,235,.14),transparent 45%);opacity:0;transition:opacity .3s}\n.mh-glow:hover{transform:translateY(-5px);border-color:#BFD0F5;box-shadow:0 30px 50px -30px rgba(37,99,235,.5)}\n.mh-glow:hover::before{opacity:1}\n.mh-glow>*{position:relative}\n.mh-ico{width:48px;height:48px;border-radius:15px;display:grid;place-items:center;color:#fff;margin-bottom:16px}\n.mh-i1{background:linear-gradient(135deg,#2563EB,#06B6D4)}.mh-i2{background:linear-gradient(135deg,#7C3AED,#EC4899)}\n.mh-i3{background:linear-gradient(135deg,#0EA5E9,#2563EB)}.mh-i4{background:linear-gradient(135deg,#F59E0B,#EF4444)}\n.mh-h3{font-size:20px;font-weight:700;letter-spacing:-.01em;display:flex;align-items:center;gap:10px;flex-wrap:wrap}\n.mh-card-p{color:var(--muted);margin-top:8px;font-size:15px}\n\n/* roles */\n.mh-seg{display:inline-flex;background:#F1F5F9;border-radius:16px;padding:5px;margin-top:28px;position:relative}\n.mh-seg button{position:relative;z-index:1;padding:11px 24px;border-radius:12px;font-weight:700;font-size:15px;color:#64748B;transition:color .25s;min-height:44px}\n.mh-seg button.on{color:#fff}\n.mh-seg-pill{position:absolute;inset:0;border-radius:12px;background:linear-gradient(135deg,#2563EB,#7C3AED);box-shadow:0 10px 24px -12px rgba(37,99,235,.9)}\n.mh-roles{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin-top:40px;align-items:center}\n@media(max-width:860px){.mh-roles{grid-template-columns:1fr}}\n.mh-list li{display:flex;gap:14px;padding:14px 0;border-bottom:1px solid var(--line);font-size:17px;font-weight:500}\n.mh-list li:last-child{border:0}\n.mh-tick-ico{flex:none;width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:#DBEAFE;color:#1D4ED8;margin-top:1px}\n\n/* dark demo */\n.mh-dark{background:radial-gradient(900px 420px at 15% 0,rgba(37,99,235,.35),transparent 60%),radial-gradient(700px 400px at 100% 100%,rgba(124,58,237,.3),transparent 60%),var(--navy);color:#fff;overflow:hidden}\n.mh-demo{max-width:820px;margin:52px auto 0;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:28px;padding:28px;backdrop-filter:blur(10px)}\n.mh-demo-top{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}\n.mh-lbl{font-size:12px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#93A4C0;margin:24px 0 10px}\n.mh-chips{display:flex;flex-wrap:wrap;gap:10px;min-height:44px}\n.mh-chip{display:inline-flex;align-items:center;gap:8px;padding:9px 16px;border-radius:999px;font-weight:600;font-size:14px;transition:all .4s}\n.mh-chip.self{border:1px dashed #8EA0BF;color:#C4D0E4}\n.mh-chip.valid{background:linear-gradient(135deg,#2563EB,#7C3AED);color:#fff;box-shadow:0 10px 26px -10px rgba(99,102,241,.9)}\n.mh-sim{margin-top:24px;border-radius:18px;padding:18px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.12)}\n.mh-sim .mh-meter-bar{background:rgba(255,255,255,.12)}\n.mh-sim .mh-meter-top{color:#B6C3DA}\n.mh-demo-note{margin-top:20px;font-size:13px;color:#93A4C0}\n.mh-btn-glass{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2);color:#fff}\n.mh-btn-glass:hover{background:rgba(255,255,255,.18)}\n.mh-btn-light{background:#fff;color:#1E3A8A}\n\n/* portfolio */\n.mh-pf{max-width:880px;margin:52px auto 0;display:grid;grid-template-columns:.8fr 1.2fr;gap:20px}\n@media(max-width:760px){.mh-pf{grid-template-columns:1fr}}\n.mh-pf-card{background:#fff;border:1px solid var(--line);border-radius:26px;padding:26px;box-shadow:0 40px 70px -40px rgba(30,58,138,.5)}\n.mh-ring{width:140px;height:140px;margin:14px auto;position:relative}\n.mh-ring svg{width:100%;height:100%;transform:rotate(-90deg)}\n.mh-ring-mid{position:absolute;inset:0;display:grid;place-items:center;text-align:center;font-weight:800;font-size:13px;color:var(--muted)}\n.mh-ev{display:flex;gap:12px;align-items:flex-start;padding:12px 0;border-top:1px solid var(--line);font-size:14px}\n.mh-ev:first-of-type{border-top:0}\n\n/* compare */\n.mh-cmp{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:52px;align-items:stretch}\n@media(max-width:820px){.mh-cmp{grid-template-columns:1fr}}\n.mh-cmp-a{border:2px dashed #CBD5E1;border-radius:26px;padding:30px;background:#F8FAFC}\n.mh-cmp-b{border-radius:26px;padding:2px;background:linear-gradient(135deg,#2563EB,#7C3AED,#06B6D4)}\n.mh-cmp-b>div{background:#fff;border-radius:24px;padding:30px;height:100%}\n.mh-claim{color:#94A3B8;font-style:italic;padding:12px 0;border-bottom:1px dashed #CBD5E1;display:flex;justify-content:space-between;gap:10px}\n.mh-claim:last-child{border:0}\n\n/* talent + roadmap */\n.mh-talent{max-width:760px;margin:0 auto;border:1.5px dashed #A8B6CE;border-radius:30px;padding:44px 28px;text-align:center;background:linear-gradient(180deg,#F8FAFF,#fff);position:relative;overflow:hidden}\n.mh-skel{display:flex;gap:12px;align-items:center;margin:12px auto 0;max-width:420px;filter:blur(3px);opacity:.7}\n.mh-skel i{display:block;height:12px;border-radius:99px;background:#CBD5E1}\n.mh-road{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:52px}\n@media(max-width:760px){.mh-road{grid-template-columns:1fr}}\n.mh-road-card{border:1px solid var(--line);border-radius:24px;padding:28px;background:#fff}\n.mh-road-card li{display:flex;align-items:center;gap:12px;padding:10px 0;font-weight:500}\n\n/* cta + footer */\n.mh-cta{position:relative;overflow:hidden;border-radius:34px;padding:84px 24px;text-align:center;color:#fff;background:linear-gradient(135deg,#1D4ED8,#5B21B6)}\n.mh-cta h2{font-size:clamp(2rem,4.2vw,3.2rem);letter-spacing:-.03em;font-weight:800;line-height:1.1;position:relative}\n.mh-cta p{color:#D6E0FF;margin:16px auto 32px;max-width:520px;font-size:18px;position:relative}\n.mh-cta .mh-btn{position:relative}\n.mh-footer{background:#070E1A;color:#94A3B8;padding:48px 0}\n.mh-foot-in{display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap;align-items:center}\n.mh-foot-links{display:flex;flex-wrap:wrap;gap:8px 22px}\n.mh-foot-links a{font-size:14px;transition:color .2s}\n.mh-foot-links a:hover{color:#fff}\n\n/* keyframes */\n@keyframes mh-shine{to{background-position:220% center}}\n@keyframes mh-drift{0%,100%{transform:translate(0,0) scale(1)}50%{transform:translate(40px,-30px) scale(1.1)}}\n@keyframes mh-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-12px)}}\n@keyframes mh-bar{0%,100%{transform:scaleY(.2)}50%{transform:scaleY(1)}}\n@keyframes mh-pulse{0%{box-shadow:0 0 0 0 rgba(16,185,129,.55)}70%{box-shadow:0 0 0 10px rgba(16,185,129,0)}100%{box-shadow:0 0 0 0 rgba(16,185,129,0)}}\n@keyframes mh-scroll{to{transform:translateX(-50%)}}\n@keyframes mh-sheen{0%,60%{left:-120%}100%{left:160%}}\n@keyframes mh-fill{from{width:0}to{width:100%}}\n@media(prefers-reduced-motion:reduce){.mh *,.mh *::before,.mh *::after{animation:none!important;transition:none!important}}\n","shared.tsx":"'use client'\n\nimport type { ReactNode, MouseEvent } from 'react'\nimport { motion, useReducedMotion } from 'framer-motion'\n\nexport type CtaProps = { onAuth: () => void }\n\nexport function Reveal({ children, delay = 0, className }: { children: ReactNode; delay?: number; className?: string }) {\n  const reduce = useReducedMotion()\n  if (reduce) return <div className={className}>{children}</div>\n  return (\n    <motion.div\n      className={className}\n      initial={{ opacity: 0, y: 28 }}\n      whileInView={{ opacity: 1, y: 0 }}\n      viewport={{ once: true, margin: '-70px' }}\n      transition={{ duration: 0.6, delay, ease: [0.22, 1, 0.36, 1] }}\n    >\n      {children}\n    </motion.div>\n  )\n}\n\nexport function PreviewBadge({ label = 'Example preview' }: { label?: string }) {\n  return <span className=\"mh-badge mh-b-preview\">{label}</span>\n}\n\nconst STATUS = { live: ['Live', 'mh-b-live'], soon: ['Coming soon', 'mh-b-soon'], planned: ['Planned', 'mh-b-planned'] } as const\nexport function StatusBadge({ status }: { status: keyof typeof STATUS }) {\n  return <span className={`mh-badge ${STATUS[status][1]}`}>{STATUS[status][0]}</span>\n}\n\nexport function SectionHeader({ eyebrow, title, description }: { eyebrow?: string; title: ReactNode; description?: string }) {\n  return (\n    <Reveal className=\"mh-head\">\n      {eyebrow && <span className=\"mh-eyebrow\">{eyebrow}</span>}\n      <h2 className=\"mh-h2\">{title}</h2>\n      {description && <p className=\"mh-lead\">{description}</p>}\n    </Reveal>\n  )\n}\n\nexport function GlowCard({ children, className = '' }: { children: ReactNode; className?: string }) {\n  const move = (e: MouseEvent<HTMLDivElement>) => {\n    const r = e.currentTarget.getBoundingClientRect()\n    e.currentTarget.style.setProperty('--mx', `${e.clientX - r.left}px`)\n    e.currentTarget.style.setProperty('--my', `${e.clientY - r.top}px`)\n  }\n  return (\n    <div className={`mh-glow ${className}`} onMouseMove={move}>\n      {children}\n    </div>\n  )\n}\n\nexport function Waveform({ bars = 30 }: { bars?: number }) {\n  return (\n    <div className=\"mh-wave\" aria-hidden=\"true\">\n      {Array.from({ length: bars }).map((_, i) => (\n        <i key={i} style={{ animationDelay: `${(i % 10) * 0.11}s`, animationDuration: `${0.9 + (i % 5) * 0.15}s` }} />\n      ))}\n    </div>\n  )\n}\n\nexport function Meter({ label, value }: { label: string; value: number }) {\n  return (\n    <div className=\"mh-meter\">\n      <div className=\"mh-meter-top\"><span>{label}</span></div>\n      <div className=\"mh-meter-bar\"><i style={{ width: `${value}%` }} /></div>\n    </div>\n  )\n}\n"}

const root = process.cwd()
const target = path.join(root, 'src', 'components', 'marketing')
const log = (m) => console.log(m)

if (!fs.existsSync(path.join(root, 'package.json')) || !fs.existsSync(path.join(root, 'src'))) {
  console.error('ERROR: run this from your project root (needs package.json and src/).')
  process.exit(1)
}

// 1. Backup OUTSIDE the project so lint/tsc ignore it
if (fs.existsSync(target)) {
  const stamp = new Date().toISOString().replace(/[:.]/g, '-')
  const backup = path.join(os.homedir(), 'mmi-backups', 'marketing-' + stamp)
  fs.mkdirSync(path.dirname(backup), { recursive: true })
  fs.cpSync(target, backup, { recursive: true })
  log('Backed up previous files to ' + backup)
}

// 2. Dependency checks
const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'))
const deps = { ...pkg.dependencies, ...pkg.devDependencies }
let anim = 'framer-motion'
if (!deps['framer-motion'] && deps['motion']) anim = 'motion/react'
if (!deps['framer-motion'] && !deps['motion']) log('WARNING: framer-motion missing. Run: npm i framer-motion')
if (!deps['lucide-react']) log('WARNING: lucide-react missing. Run: npm i lucide-react')

// 3. Check page.tsx wiring
const pagePath = path.join(root, 'src', 'app', 'page.tsx')
if (fs.existsSync(pagePath)) {
  const page = fs.readFileSync(pagePath, 'utf8')
  if (!/<GuestHomepage[\s\S]*?onAuth=/.test(page)) log('WARNING: <GuestHomepage> in src/app/page.tsx does not pass onAuth={...}. Add it or rename the prop in GuestHomepage.tsx.')
}

// 4. Write files
fs.mkdirSync(target, { recursive: true })
for (const [name, content] of Object.entries(FILES)) {
  const out = anim === 'framer-motion' ? content : content.replaceAll("from 'framer-motion'", "from '" + anim + "'")
  fs.writeFileSync(path.join(target, name), out)
}
log('Wrote ' + Object.keys(FILES).length + ' files to src/components/marketing/')

// 5. Type check
if (!process.argv.includes('--no-check')) {
  log('\nRunning type check...')
  try { execSync('npx tsc --noEmit', { stdio: 'inherit', cwd: root }); log('Type check passed.') }
  catch { log('Type check reported errors above.') }
}
log('\nDone. Now run: npm run dev   (hard refresh the browser: Cmd+Shift+R)')
